--
-- Name: update_conversation_message_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_conversation_message_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE conversation SET
        last_message_at = NEW.timestamp,
        message_count = message_count + 1,
        approximate_token_count = approximate_token_count + (length(NEW.content::text) / 4)
    WHERE conversation_id = NEW.conversation_id;
    RETURN NEW;
END;
$$;

